  "misconception": {
    "pack_id": "M04",
    "wrong": "Пористость и проницаемость — одно и то же, поэтому время расформирования сразу даёт и то и другое.",
    "right": "Это разные свойства породы. Время расформирования говорит о проницаемости качественно, а пористость — отдельный показатель, с которым время сопоставляют.",
    "claims": ["c1", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Результаты повторных временных замеров одного и того же пласта, сделанных в разное время.", "claims": ["c1", "c2"], "hypothesis": false},
      {"text": "Пористость пластов, найденная другими методами.", "claims": ["c3"], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Качественная оценка проницаемости: в каком пласте зона проникновения расформировывается быстрее.", "claims": ["c1", "c2"], "hypothesis": false},
      {"text": "Нижнее значение пористости для коллекторов.", "claims": ["c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Чувствительность метода ниже искомого значения пористости: нижнюю границу тогда не установить.", "claims": ["c4"], "hypothesis": false},
      {"text": "Время даёт качественный признак, а не точное число проницаемости.", "claims": ["c1"], "hypothesis": false},
      {"text": "Правило работает как тенденция «обычно»: для части пород связь может не выполняться.", "claims": ["c2"], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT05",
    "analogy": "Повторные чтения одного адреса: первое видит «кэш» (фильтрат), следующие уже видят исходные данные. Скорость смены показывает свойство хранилища.",
    "breaks_where": "У кэша фиксированного срока жизни нет: скорость смены зависит от раствора и пористости. Результат качественный, а не числовой.",
    "hypothesis": true
  },
  "now_nuance": {
    "text": "Сегодня для повторных замеров в обсаженной скважине чаще используют компенсированные нейтронные приборы и импульсные генераторы нейтронов. Проницаемость оценивают по набору данных, а не по одному времени.",
    "hypothesis": true
  },
  "threshold": {
    "is_threshold": false,
    "why": "Узел даёт полезный приём: повторный замер можно читать как признак проницаемости. Но ключевая идея уже задана в соседних узлах о повторных замерах."
  },
  "inefficiency": {
    "inputs": [
      {"text": "Результаты повторных временных замеров в пластах с разными свойствами.", "claims": ["c1", "c2"], "hypothesis": false},
      {"text": "Оценки пористости каждого пласта, полученные из других данных.", "claims": ["c3"], "hypothesis": true}
    ],
    "manual_steps": [
      {"text": "Сопоставить результаты временных замеров с пористостью каждого пласта.", "claims": ["c3"], "hypothesis": false},
      {"text": "Занести результаты по пластам в таблицу для сравнения.", "claims": [], "hypothesis": true}
    ],
    "judgment_points": [
      {"text": "Решить, достаточна ли чувствительность метода для нужного значения пористости.", "claims": ["c4"], "hypothesis": false},
      {"text": "Решить, какое время расформирования считать коротким для данного района.", "claims": ["c2"], "hypothesis": true}
    ],
    "time": [
      {"text": "Ожидание расформирования: для особо проницаемых пластов это несколько десятков часов.", "claims": ["c5"], "hypothesis": false},
      {"text": "Ожидание между повторными замерами, которое нужно согласовать с работой скважины.", "claims": [], "hypothesis": true}
    ],
    "typical_errors": [
      {"text": "Принять качественный признак за точное число проницаемости.", "claims": ["c1"], "hypothesis": false},
      {"text": "Получить завышенный нижний предел пористости, не проверив чувствительность метода.", "claims": ["c4"], "hypothesis": false}
    ]
  },
  "videoability": {
    "time_change": true,
    "invisible_visible": true,
    "scale_jump": false,
    "counterintuitive": false,
